<?php require '_layout.php';$db=db();$fr=$_GET['from']??date('Y-m-d',strtotime('-29 day'));$to=$_GET['to']??date('Y-m-d');$a=[$fr,$to];$W="o.created_at>=? AND o.created_at<DATE_ADD(?,INTERVAL 1 DAY) AND o.status<>'cancelled'";
$q=function($sql)use($db,$a){$s=$db->prepare($sql);$s->execute($a);return $s;};
$k=$q("SELECT COUNT(*) n,COALESCE(SUM(total),0) t,COALESCE(AVG(total),0) av,COALESCE(SUM(discount),0) dc,COALESCE(SUM(method='delivery'),0) dl FROM orders o WHERE $W")->fetch();
ahead('Reports','reports.php');?><form class="flt"><label>From <input type="date" name="from" value="<?=e($fr)?>"></label><label>To <input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Show</button><a class="btn ghost" href="export.php?t=orders&from=<?=e($fr)?>&to=<?=e($to)?>">Export orders CSV</a><a class="btn ghost" href="export.php?t=items&from=<?=e($fr)?>&to=<?=e($to)?>">Export items CSV</a></form>
<div class="cards"><div class="kc"><small>Orders</small><b><?=$k['n']?></b></div><div class="kc"><small>Sales</small><b><?=money($k['t'])?></b></div><div class="kc"><small>Average order</small><b><?=money($k['av'])?></b></div><div class="kc"><small>Delivery / collection</small><b><?=$k['dl']?> / <?=$k['n']-$k['dl']?></b></div><div class="kc"><small>Promo discounts given</small><b><?=money($k['dc'])?></b></div></div>
<div class="two"><section class="pn"><h3>Sales by aisle</h3><table><?php foreach($q("SELECT COALESCE(t.name,s.name) c,SUM(i.line_total) t FROM order_items i JOIN orders o ON o.id=i.order_id JOIN products p ON p.sku=i.sku JOIN categories s ON s.id=p.category_id LEFT JOIN categories t ON t.id=s.parent_id WHERE $W GROUP BY c ORDER BY t DESC") as $r): ?><tr><td><?=e($r['c'])?></td><td class="r"><?=money($r['t'])?></td></tr><?php endforeach; ?></table></section>
<section class="pn"><h3>Best sellers</h3><table><?php foreach($q("SELECT i.name,COUNT(*) n,SUM(i.line_total) t FROM order_items i JOIN orders o ON o.id=i.order_id WHERE $W GROUP BY i.name ORDER BY t DESC LIMIT 15") as $r): ?><tr><td><?=e($r['name'])?></td><td><?=$r['n']?> orders</td><td class="r"><?=money($r['t'])?></td></tr><?php endforeach; ?></table></section></div>
<section class="pn"><h3>Sales by day</h3><table><?php foreach($q("SELECT DATE(o.created_at) d,COUNT(*) n,SUM(o.total) t FROM orders o WHERE $W GROUP BY d ORDER BY d DESC") as $r): ?><tr><td><?=e($r['d'])?></td><td><?=$r['n']?> orders</td><td class="r"><?=money($r['t'])?></td></tr><?php endforeach; ?></table></section><?php afoot();
